//! Every native fixture read through a Channel, as C reads it: the status of
//! each read and the warnings it leaves for items no class loader reads
//! (channel.c `ClearValues`). C reads every fixture written by the C library
//! without a warning, so a warning here is an item a Rust loader leaves
//! unread that C's reads. The fixtures C cannot read (card headers, and
//! IntraMaps with no registered transformation) fail in the same way.
//!
//! `fixture_read_warnings_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/fixture_read_warnings_probe.c`, and lists only the
//! fixtures C gives a warning or an error for.

#[rustfmt::skip]
#[path = "fixture_read_warnings_oracle/cases.rs"]
mod cases;

use std::path::{Path, PathBuf};

use starlink_ast::{Channel, NativeChannel, StringSource};

/// Fixtures the port reads differently from C, with the reason.
const EXCLUDED: &[(&str, &str)] = &[(
    "./serialisation/frame_in_map_slot.ast",
    "a CmpFrame in a Mapping slot, which the port refuses by design \
     (test_frame_in_map_slot.rs)",
)];

fn excluded(file: &str) -> bool {
    EXCLUDED.iter().any(|(f, _)| *f == file)
}

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// The native fixtures, as `./`-prefixed paths relative to the fixtures
/// directory, as the probe lists them.
fn native_fixtures(dir: &Path, out: &mut Vec<String>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            native_fixtures(&path, out);
        } else if matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("map" | "simp" | "ast" | "native")
        ) {
            let rel = path.strip_prefix(fixtures()).unwrap();
            out.push(format!("./{}", rel.display()));
        }
    }
}

/// C's reads of `file`, those listed by the probe.
fn c_reads(file: &str) -> Vec<(i32, Vec<String>)> {
    cases::CASES
        .iter()
        .find(|(f, _)| *f == file)
        .map(|(_, reads)| {
            reads
                .iter()
                .map(|(s, w)| (*s, w.iter().map(|m| m.to_string()).collect()))
                .filter(|(s, w): &(i32, Vec<String>)| *s != 0 || !w.is_empty())
                .collect()
        })
        .unwrap_or_default()
}

/// Each read of `fixture`, up to the end or an error, as `(status,
/// warnings)`, listing only reads that fail or warn.
fn reads(fixture: &str) -> Vec<(i32, Vec<String>)> {
    let text = std::fs::read_to_string(fixtures().join(fixture)).unwrap();
    let mut ch = NativeChannel::new();
    ch.set_source(Box::new(StringSource::new(&text)));
    let mut out = Vec::new();
    for _ in 0..10 {
        let (status, done) = match ch.read() {
            Ok(Some(_)) => (0, false),
            Ok(None) => (0, true),
            Err(e) => (e.code() as i32, true),
        };
        let warnings = ch.warning_texts().to_vec();
        if status != 0 || !warnings.is_empty() {
            out.push((status, warnings));
        }
        if done {
            break;
        }
    }
    out
}

#[test]
fn reads_match_c() {
    let mut files = Vec::new();
    native_fixtures(&fixtures(), &mut files);
    files.sort();
    assert!(files.len() > 1000, "found only {} fixtures", files.len());
    let mut failed = Vec::new();
    for file in files.iter().filter(|f| !excluded(f)) {
        let (got, want) = (reads(file), c_reads(file));
        if got != want {
            failed.push(format!("{file}: got {got:?}, C {want:?}"));
        }
    }
    assert!(
        failed.is_empty(),
        "{} of {} fixtures differ:\n{}",
        failed.len(),
        files.len(),
        failed.join("\n")
    );
}

#[test]
fn excluded_fixtures_still_differ() {
    for (file, reason) in EXCLUDED {
        assert_ne!(
            reads(file),
            c_reads(file),
            "{file} now reads as C does; remove it from EXCLUDED ({reason})"
        );
    }
}
